UPDATE lbl_label_task_item
SET state = 'SUPERSEDED', exception_reason = NULL, updated_at = #{updatedAt}, version = version + 1
WHERE tenant_id = #{tenantId} AND store_id = #{storeId} AND sku_id = #{skuId} AND unit_id = #{unitId}
  AND item_id <> #{replacingItemId}
  AND state IN ('PENDING','PREVIEW_READY','EXCEPTION')
  AND (
    effective_at < #{effectiveAt}
    OR (effective_at = #{effectiveAt} AND scope_priority < #{scopePriority})
    OR (effective_at = #{effectiveAt} AND scope_priority = #{scopePriority}
        AND source_price_version < #{sourcePriceVersion})
    OR (effective_at = #{effectiveAt} AND scope_priority = #{scopePriority}
        AND source_price_version = #{sourcePriceVersion} AND source_price_book_id < #{sourcePriceBookId})
  )

UPDATE lbl_label_task_item
SET state = #{targetState}, exception_reason = #{exceptionReason},
    updated_at = #{updatedAt}, version = version + 1
WHERE tenant_id = #{tenantId} AND item_id = #{itemId}
  AND state = #{expectedState} AND version = #{version}
